// mlp_hls4ml_wrap.sv: arm (b) built by hls4ml 1.3.0 and Vitis HLS 2026.1 (top mlp_hls4ml, io_parallel, Latency
// strategy, reuse factor 1), with the same ports as the hand-RTL arms. The HLS Verilog is not committed: it is
// regenerated by `python -m designs.b87_ml_trading.model.hls4ml_arm --synth` and copied to build/b87/hls4ml_rtl/.
// Input: each feature minus its offset is the raw value of ap_fixed<10,4> (six fraction bits, as the integer model's
// 2^-6 input scale). Output: the argmax of the three logits, registered (ties to the lower class, as the other arms).
// LATENCY = the HLS core's 32 clocks (its csynth report, target 2.0 ns) + 1 for the argmax register; the RTL test
// checks it for every test sample. The core is run every clock (x_ap_vld held high) and validity travels in a
// shift register beside it: with x_ap_vld = in_v the generated pipeline stalls while the input is not valid, and
// a sample then waits for later ones (measured: latency 33 to 96 clocks and samples left inside; determinism.json).
module mlp_hls4ml_wrap (
    input  logic        clk,
    input  logic        rst,
    input  logic        in_v,
    input  logic [37:0] in_f,
    output logic        out_v,
    output logic [1:0]  out_cls
);
    localparam int LATENCY = 33;
    logic [9:0] x [7];
    assign x[0] = 10'(in_f[7:0]);
    assign x[1] = 10'(in_f[15:8]);
    assign x[2] = 10'(in_f[19:16]);
    assign x[3] = 10'(in_f[22:20]);
    assign x[4] = 10'(in_f[27:23]) - 10'd8;
    assign x[5] = 10'(in_f[35:28]) - 10'd128;
    assign x[6] = 10'(in_f[37:36]) - 10'd1;
    logic signed [25:0] z0, z1, z2;
    logic [LATENCY-2:0] vpipe;
    mlp_hls4ml u_hls (.ap_clk(clk), .ap_rst(rst), .ap_start(1'b1), .ap_done(), .ap_idle(), .ap_ready(),
        .x_ap_vld(1'b1), .x({x[6], x[5], x[4], x[3], x[2], x[1], x[0]}),
        .layer6_out_0(z0), .layer6_out_0_ap_vld(), .layer6_out_1(z1), .layer6_out_1_ap_vld(),
        .layer6_out_2(z2), .layer6_out_2_ap_vld());
    always_ff @(posedge clk) begin
        if (rst) begin
            vpipe <= '0;
            out_v <= 1'b0;
        end else begin
            vpipe <= {vpipe[LATENCY-3:0], in_v};
            out_v <= vpipe[LATENCY-2];
        end
        out_cls <= ((z0 >= z1) && (z0 >= z2)) ? 2'd0 : ((z1 >= z2) ? 2'd1 : 2'd2);
    end
endmodule
